SELECT COUNT(*) FROM title as t, kind_type as kt, info_type as it1, movie_info as mi1, cast_info as ci, role_type as rt, name as n, movie_keyword as mk, keyword as k, movie_companies as mc, company_type as ct, company_name as cn WHERE t.id = ci.movie_id AND t.id = mc.movie_id AND t.id = mi1.movie_id AND t.id = mk.movie_id AND mc.company_type_id = ct.id AND mc.company_id = cn.id AND k.id = mk.keyword_id AND mi1.info_type_id = it1.id AND t.kind_id = kt.id AND ci.person_id = n.id AND ci.role_id = rt.id AND (it1.id IN ('18')) AND (mi1.info in ('CBS Studio 50, New York City, New York, USA','CBS Television City - 7800 Beverly Blvd., Fairfax, Los Angeles, California, USA','General Service Studios - 1040 N. Las Palmas, Hollywood, Los Angeles, California, USA','Hal Roach Studios - 8822 Washington Blvd., Culver City, California, USA')) AND (kt.kind in ('episode')) AND (rt.role in ('actress','composer','director','miscellaneous crew')) AND (n.gender in ('f') OR n.gender IS NULL) AND (n.name_pcode_nf in ('A4523','C6235','E4213','I3541','J5162','K3145','K6235','M2346','M6216','R1634') OR n.name_pcode_nf IS NULL) AND (t.production_year <= 2015) AND (t.production_year >= 1925) AND (cn.name in ('20th Century Fox Television','ABS-CBN','American Broadcasting Company (ABC)','British Broadcasting Corporation (BBC)','Columbia Broadcasting System (CBS)','Granada Television','National Broadcasting Company (NBC)')) AND (ct.kind in ('distributors','production companies'))
